15	 * limitations under the License.
16	 */
17	package org.apache.camel.model;
18	
19	import java.util.HashMap;
20	import java.util.Map;
21	import java.util.StringJoiner;
22	import java.util.TreeMap;
23	
24	import org.apache.camel.CamelContext;
25	import org.apache.camel.Exchange;
26	import org.apache.camel.Expression;
27	import org.apache.camel.NoSuchBeanException;
28	import org.apache.camel.RouteTemplateContext;
29	import org.apache.camel.RuntimeCamelException;
30	import org.apache.camel.spi.Language;
31	import org.apache.camel.spi.ScriptingLanguage;
32	import org.apache.camel.support.ExchangeHelper;
33	import org.apache.camel.support.ObjectHelper;
34	import org.apache.camel.support.PropertyBindingSupport;
35	import org.apache.camel.support.ScriptHelper;
36	import org.apache.camel.util.StringHelper;
37	import org.apache.camel.util.function.Suppliers;
38	
39	/**
40	 * Helper to create bean instances from bean model definitions.
41	 * <p/>
42	 * Creating beans is complex as Camel support many options such as constructor, factory beans, builder beans, scripts,
43	 * and much more. This helper hides this complexity for creating bean instances.
44	 */
45	public final class BeanModelHelper {
46	
47	    private BeanModelHelper() {
48	    }
49	
50	    /**
51	     * Creates a new bean.
52	     *
53	     * @param  def       the bean model
54	     * @param  context   the camel context
55	     * @return           the created bean instance
56	     * @throws Exception is thrown if error creating the bean
57	     */
58	    public static Object newInstance(BeanFactoryDefinition def, CamelContext context) throws Exception {
59	        Object target;
60	
61	        String type = def.getType();
62	        if (!type.startsWith("#")) {
63	            type = "#class:" + type;
64	        }
65	
66	        // script bean
67	        if (def.getScriptLanguage() != null && def.getScript() != null) {
68	            String script = resolveScript(context, def);
69	            // create bean via the script
70	            final Language lan = context.resolveLanguage(def.getScriptLanguage());
71	            final ScriptingLanguage slan = lan instanceof ScriptingLanguage sl ? sl : null;
72	            String fqn = def.getType();
73	            if (fqn.startsWith("#class:")) {
74	                fqn = fqn.substring(7);
75	            }
76	            final Class<?> clazz = context.getClassResolver().resolveMandatoryClass(fqn);
77	            if (slan != null) {
78	                // scripting language should be evaluated with context as binding
79	                Map<String, Object> bindings = new HashMap<>();
80	                bindings.put("context", context);
81	                target = slan.evaluate(script, bindings, clazz);
82	            } else {
83	                Exchange dummy = ExchangeHelper.getDummy(context);
84	                String text = ScriptHelper.resolveOptionalExternalScript(context, dummy, script);
85	                Expression exp = lan.createExpression(text);
86	                target = exp.evaluate(dummy, clazz);
87	            }
88	
89	            // a bean must be created
90	            if (target == null) {
91	                throw new NoSuchBeanException(def.getName(), "Creating bean using script returned null");
92	            }
93	        } else if (def.getBuilderClass() != null) {
94	            // builder class and method
95	            Class<?> clazz = context.getClassResolver().resolveMandatoryClass(def.getBuilderClass());
96	            Object builder = context.getInjector().newInstance(clazz);
97	            String bm = def.getBuilderMethod() != null ? def.getBuilderMethod() : "build";
98	
99	            // create bean via builder and assign as target output
100	            target = PropertyBindingSupport.build()
101	                    .withCamelContext(context)
102	                    .withTarget(builder)
103	                    .withRemoveParameters(true)
104	                    .withProperties(def.getProperties())
105	                    .build(Object.class, bm);
106	        } else {
107	            // factory bean/method
108	            if (def.getFactoryBean() != null && def.getFactoryMethod() != null) {
109	                type = type + "#" + def.getFactoryBean() + ":" + def.getFactoryMethod();
110	            } else if (def.getFactoryMethod() != null) {
111	                type = type + "#" + def.getFactoryMethod();
112	            }
113	            // property binding support has constructor arguments as part of the type
114	            StringJoiner ctr = new StringJoiner(", ");
115	            if (def.getConstructors() != null && !def.getConstructors().isEmpty()) {
116	                // need to sort constructor args based on index position
117	                Map<Integer, Object> sorted = new TreeMap<>(def.getConstructors());
118	                for (Object val : sorted.values()) {
119	                    String text = val.toString();
120	                    if (!StringHelper.isQuoted(text)) {
121	                        text = "\"" + text + "\"";
122	                    }
123	                    ctr.add(text);
124	                }
125	                type = type + "(" + ctr + ")";
126	            }
127	
128	            target = PropertyBindingSupport.resolveBean(context, type);
129	        }
130	
131	        // do not set properties when using #type as it uses an existing shared bean
132	        boolean setProps = !type.startsWith("#type");
133	        if (setProps) {
134	            // set optional properties on created bean
135	            if (def.getProperties() != null && !def.getProperties().isEmpty()) {
136	                PropertyBindingSupport.setPropertiesOnTarget(context, target, def.getProperties());
137	            }
138	        }
139	
140	        return target;
141	    }
142	
143	    /**
144	     * Creates and binds the bean to the route-template repository (local beans for kamelets).
145	     *
146	     * @param  def                  the bean factory to bind.
147	     * @param  routeTemplateContext the context into which the bean factory should be bound.
148	     * @throws Exception            if an error occurs while trying to bind the bean factory
149	     */
150	    public static void bind(BeanFactoryDefinition<?> def, RouteTemplateContext routeTemplateContext)
151	            throws Exception {
152	
153	        final Map<String, Object> props = new HashMap<>();
154	        if (def.getProperties() != null) {
155	            props.putAll(def.getProperties());
156	        }
157	        if (def.getBeanSupplier() != null) {
158	            if (props.isEmpty()) {
159	                // bean class is optional for supplier
160	                if (def.getBeanClass() != null) {
161	                    routeTemplateContext.bind(def.getName(), def.getBeanClass(), def.getBeanSupplier());
162	                } else {
163	                    routeTemplateContext.bind(def.getName(), def.getBeanSupplier());
164	                }
165	            }
166	        } else if (def.getScript() != null && def.getScriptLanguage() != null) {
167	            final CamelContext camelContext = routeTemplateContext.getCamelContext();
168	            final Language lan = camelContext.resolveLanguage(def.getScriptLanguage());
169	            final Class<?> clazz;
170	            if (def.getBeanClass() != null) {
171	                clazz = def.getBeanClass();
172	            } else if (def.getType() != null) {
173	                String fqn = def.getType();
174	                if (fqn.contains(":")) {
175	                    fqn = StringHelper.after(fqn, ":");
176	                }
177	                clazz = camelContext.getClassResolver().resolveMandatoryClass(fqn);
178	            } else {
179	                clazz = Object.class;
180	            }
181	            final String script = resolveScript(camelContext, def);
182	            final ScriptingLanguage slan = lan instanceof ScriptingLanguage sl ? sl : null;
183	            if (slan != null) {
184	                // scripting language should be evaluated with route template context as binding
185	                // and memorize so the script is only evaluated once and the local bean is the same
186	                // if a route template refers to the local bean multiple times
187	                routeTemplateContext.bind(def.getName(), clazz, Suppliers.memorize(() -> {
188	                    Object local;
189	                    Map<String, Object> bindings = new HashMap<>();
190	                    // use rtx as the short-hand name, as context would imply its CamelContext
191	                    bindings.put("rtc", routeTemplateContext);
192	                    try {
193	                        local = slan.evaluate(script, bindings, Object.class);
194	                        if (!props.isEmpty()) {
195	                            PropertyBindingSupport.setPropertiesOnTarget(camelContext, local, props);
196	                        }
197	                        if (def.getInitMethod() != null) {
198	                            ObjectHelper.invokeMethodSafe(def.getInitMethod(), local);
199	                        }
200	                        if (def.getDestroyMethod() != null) {
201	                            routeTemplateContext.registerDestroyMethod(def.getName(), def.getDestroyMethod());
202	                        }
203	                    } catch (Exception e) {
204	                        throw new IllegalStateException(
205	                                "Cannot create bean: " + def.getType(), e);
206	                    }
207	                    return local;
208	                }));
209	            } else {
210	                // exchange based languages needs a dummy exchange to be evaluated
211	                // and memorize so the script is only evaluated once and the local bean is the same
212	                // if a route template refers to the local bean multiple times
213	                routeTemplateContext.bind(def.getName(), clazz, Suppliers.memorize(() -> {
214	                    try {
215	                        Exchange dummy = ExchangeHelper.getDummy(camelContext);
216	                        String text = ScriptHelper.resolveOptionalExternalScript(camelContext, dummy, script);
217	                        if (text != null) {
218	                            Expression exp = lan.createExpression(text);
219	                            Object local = exp.evaluate(dummy, clazz);
220	                            if (!props.isEmpty()) {
221	                                PropertyBindingSupport.setPropertiesOnTarget(camelContext, local, props);
222	                            }
223	                            if (def.getInitMethod() != null) {
224	                                try {
225	                                    ObjectHelper.invokeMethodSafe(def.getInitMethod(), local);
226	                                } catch (Exception e) {
227	                                    throw RuntimeCamelException.wrapRuntimeException(e);
228	                                }
229	                            }
230	                            if (def.getDestroyMethod() != null) {
231	                                routeTemplateContext.registerDestroyMethod(def.getName(), def.getDestroyMethod());
232	                            }
233	                            return local;
234	                        } else {
235	                            return null;
236	                        }
237	                    } catch (Exception e) {
238	                        throw new IllegalStateException(
239	                                "Cannot create bean: " + def.getType(), e);
240	                    }
241	                }));
242	            }
243	        } else if (def.getBeanClass() != null || def.getType() != null) {
244	            String type = def.getType();
245	            if (type == null) {
246	                type = def.getBeanClass().getName();
247	            }
248	            if (!type.startsWith("#")) {
249	                type = "#class:" + type;
250	            }
251	            // factory bean/method
252	            if (def.getFactoryBean() != null && def.getFactoryMethod() != null) {
253	                type = type + "#" + def.getFactoryBean() + ":" + def.getFactoryMethod();
254	            } else if (def.getFactoryMethod() != null) {
255	                type = type + "#" + def.getFactoryMethod();
256	            }
257	            // property binding support has constructor arguments as part of the type
258	            StringJoiner ctr = new StringJoiner(", ");
259	            if (def.getConstructors() != null && !def.getConstructors().isEmpty()) {
260	                // need to sort constructor args based on index position
261	                Map<Integer, Object> sorted = new TreeMap<>(def.getConstructors());
262	                for (Object val : sorted.values()) {
263	                    String text = val.toString();
264	                    if (!StringHelper.isQuoted(text)) {
265	                        text = "\"" + text + "\"";
266	                    }
267	                    ctr.add(text);
268	                }
269	                type = type + "(" + ctr + ")";
270	            }
271	            final String classType = type;
272	
273	            final CamelContext camelContext = routeTemplateContext.getCamelContext();
274	            routeTemplateContext.bind(def.getName(), Object.class, Suppliers.memorize(() -> {
275	                try {
276	                    Object local = PropertyBindingSupport.resolveBean(camelContext, classType);
277	
278	                    // do not set properties when using #type as it uses an existing shared bean
279	                    boolean setProps = !classType.startsWith("#type");
280	                    if (setProps) {
281	                        // set optional properties on created bean
282	                        if (def.getProperties() != null && !def.getProperties().isEmpty()) {
283	                            PropertyBindingSupport.setPropertiesOnTarget(camelContext, local, def.getProperties());
284	                        }
285	                    }
286	                    if (def.getInitMethod() != null) {
287	                        ObjectHelper.invokeMethodSafe(def.getInitMethod(), local);
288	                    }
289	                    if (def.getDestroyMethod() != null) {
290	                        routeTemplateContext.registerDestroyMethod(def.getName(), def.getDestroyMethod());
291	                    }
292	                    return local;
293	                } catch (Exception e) {
294	                    throw new IllegalStateException(
295	                            "Cannot create bean: " + def.getType(), e);
296	                }
297	            }));
298	        } else {
299	            // invalid syntax for the local bean, so lets report an exception
300	            throw new IllegalArgumentException(
301	                    "Route template local bean: " + def.getName() + " has invalid type syntax: " + def.getType()
302	                                               + ". To refer to a class then prefix the value with #class such as: #class:fullyQualifiedClassName");
303	        }
304	    }
305	
306	    private static String resolveScript(CamelContext camelContext, BeanFactoryDefinition<?> def) {
307	        String answer = def.getScript();
308	        if (answer != null && !"false".equals(def.getScriptPropertyPlaceholders())) {
309	            answer = camelContext.resolvePropertyPlaceholders(answer);
310	        }
311	        return answer;
312	    }
313	}
